    ],
    previousRoad: [
      {
        no: '1',
        txt1: 'Bootstrap : 어드민 페이지 구축',
      },
      {
        no: '2',
        txt1: 'JQuery 심화 : 필수[선택] 동의 체크',
      },
      {
        no: '3',
        txt1: 'CSS 전처리기 : SCSS',
