    window.addEventListener('click', this.showPop, false)
    window.addEventListener('click', this.closePop, false)
    window.addEventListener('click', this.showContents, false)
  },
  beforeUnmount() {
    document.removeEventListener('click', this.receiveStatus, true)

    window.removeEventListener('click', this.showPrgms, false)
    window.removeEventListener('click', this.showPop, false)
    window.removeEventListener('click', this.closePop, false)
    window.removeEventListener("click", this.showContents, false)
