  // },
  // beforeUpdate() {
  //   document.removeEventListener('click', this.receiveStatus, true)
  // },
  methods: {
    receiveStatus() {
      let detector = document.querySelector('.toggle_luminosity');

      detector.addEventListener('click', (e) => {
        let app = document.querySelector('#app'),
            modeLight = document.querySelector('.toggle_luminosity img'),
            modeDark = modeLight.nextElementSibling;

        console.log(modeLight, modeDark)
        console.log(e.target.classList)
          if(e.target.classList.contains('light') === true) {
            console.log('라이트 모드 감지')
            app.classList.add('dark-mode')
            modeLight.classList.remove('on')
            modeDark.classList.add('on')
          } 
          if(e.target.classList.contains('dark') === true) {
            console.log('다크 모드 감지')
            app.classList.remove('dark-mode')
            modeLight.classList.add('on')
            modeDark.classList.remove('on')
          }
      }, true)
    },
    // receiveStatus() {
    //   let app = document.querySelector('#app'),
    //       btnMode = app.querySelector('.toggle_luminosity');
    //   console.log(app.className)
    //   btnMode.classList.add('on')

    //   if(btnMode.classList.contains('on') === true) {
    //     app.classList.add('dark-mode')
    //   } 
    //   else {
    //     app.classList.remove('dark-mode')
    //   }
    // },
    showPrgms() {
      const sortList = document.querySelector('.sortdata'),
            menu = sortList.querySelectorAll('button'),
            popZone = document.querySelector('.statusType'),
            chart = document.querySelectorAll('.chart ul li');
      // console.log(chart);
      
      if(popZone.classList.contains('closed')) {
        popZone.classList.remove('closed')
        document.querySelector('body').classList.add('active_popup')
        // document.querySelector('body').style.overflowY = 'hidden';
      }
      for(let idx2 = 0; idx2 < menu.length; idx2++) {
        menu[idx2].addEventListener('click', () => {
          menu[idx2].classList.add('active');
          chart[idx2].classList.add('active');
          for(let idx_dif2 = 0; idx_dif2 < menu.length; idx_dif2++) {
            /* 인덱스가 서로 다르면 active 클레스 제거 */  
            if(idx2 !== idx_dif2) {
              menu[idx_dif2].classList.remove('active');
              chart[idx_dif2].classList.remove('active');
            }
          }
        })
      }
    },
    showPop() {
      const popArea = document.querySelector('.statusOn'),
          setDisplay = popArea.style.display;

      if(setDisplay == '') {
        popArea.classList.remove('closed')
        document.querySelector('body').classList.add('active_popup')
        // document.querySelector('body').style.overflowY = 'hidden';
      }
    },
    closePop() {
      const prgmArea = document.querySelector('.statusOff'),
          resetDisplay = prgmArea.style.display;

      if(resetDisplay == '') {
        prgmArea.classList.add('closed')
        document.querySelector('body').classList.remove('active_popup')
        // document.querySelector('body').style.overflowY = 'auto';
      }  
    },
    showContents() {
      const tabNavi = document.querySelector('.tab_navi'),
            sortingNavis = tabNavi.querySelectorAll('li'),
            sortingConts = document.querySelectorAll('article[class^="article-box"]');
      // console.log(sortingConts);
      
      for(let idx = 0; idx < sortingNavis.length; idx++) {
        sortingNavis[idx].addEventListener('click', () => {
          sortingNavis[idx].classList.add('on');
          sortingConts[idx].classList.add('on');
          for(let idx_dif = 0; idx_dif < sortingNavis.length; idx_dif++) {
            /* 인덱스가 서로 다르면 on 클레스 제거 */  
            if(idx !== idx_dif) {
              sortingNavis[idx_dif].classList.remove('on');
              sortingConts[idx_dif].classList.remove('on');
            }
          }
        })
      }
    }
  }
}
